<?php
$filters = spmb_report_filters($scope, $_GET);
$allRows = unit_admin_spmb_rows($mainPdo, $scope);
$rows = spmb_report_rows($mainPdo, $pdo, $scope, $filters);
$counts = spmb_report_counts($rows, $scope);
$years = array_values(array_unique(array_filter(array_column($allRows, 'academic_year'))));
rsort($years);
$statusLabels = ['baru'=>'Baru','verifikasi'=>'Verifikasi','lulus'=>'Lulus','cadangan'=>'Cadangan','ditolak'=>'Ditolak','daftar_ulang'=>'Daftar Ulang'];
$allClaims = $mainPdo->query("SELECT c.*,r.level,r.student_name,r.registration_number FROM spmb_payment_claims c JOIN spmb_registrations r ON r.id=c.registration_id WHERE c.status='pending' ORDER BY c.created_at DESC,c.id DESC")->fetchAll();
$pendingClaims = array_values(array_filter($allClaims, static fn(array $item): bool => school_unit_slug($item['level']) === $scope));
$verifiedClaimRows = $mainPdo->query("SELECT c.*,r.level,r.student_name,r.registration_number FROM spmb_payment_claims c JOIN spmb_registrations r ON r.id=c.registration_id WHERE c.status='verified' ORDER BY c.reviewed_at DESC,c.id DESC")->fetchAll();
$verifiedClaims = array_slice(array_values(array_filter($verifiedClaimRows, static fn(array $item): bool => school_unit_slug($item['level']) === $scope)), 0, 30);
$today = date('Y-m-d');
$todayRegistrations = count(array_filter($allRows, static fn(array $item): bool => substr((string)$item['created_at'],0,10) === $today));
$unitPaid = array_sum(array_map(static fn(array $item): float => (float)$item['payment_amount'], $allRows));
$verifiedTodayRows = $mainPdo->query("SELECT c.claimed_amount,r.level FROM spmb_payment_claims c JOIN spmb_registrations r ON r.id=c.registration_id WHERE c.status='verified' AND DATE(c.reviewed_at)=CURDATE()")->fetchAll();
$verifiedToday = array_sum(array_map(static fn(array $item): float => school_unit_slug($item['level']) === $scope ? (float)$item['claimed_amount'] : 0.0, $verifiedTodayRows));
$sharePaymentUrl = null;
if (isset($_GET['payment_link_spmb'])) {
    $shareId = (int)$_GET['payment_link_spmb'];
    $shareQuery = $mainPdo->prepare('SELECT level FROM spmb_registrations WHERE id=?');
    $shareQuery->execute([$shareId]);
    $shareLevel = $shareQuery->fetchColumn();
    if ($shareLevel && school_unit_slug((string)$shareLevel) === $scope) {
        $sharePaymentUrl = spmb_payment_url(spmb_payment_link_token($mainPdo,$shareId));
    }
}
?>
<style>
