</style>
<div class="spmb-daily"><div><span>Pendaftar hari ini</span><strong><?php echo $todayRegistrations; ?></strong></div><div><span>Bukti menunggu pemeriksaan</span><strong><?php echo count($pendingClaims); ?></strong></div><div><span>Terverifikasi hari ini</span><strong>Rp <?php echo number_format($verifiedToday,0,',','.'); ?></strong></div><div><span>Total terbayar unit</span><strong>Rp <?php echo number_format($unitPaid,0,',','.'); ?></strong></div></div>
<?php if($sharePaymentUrl): ?><section class="panel"><h2>Tautan Kirim Bukti Pembayaran</h2><p>Bagikan hanya kepada orang tua pendaftar terkait.</p><p><a href="<?php echo unit_e($sharePaymentUrl); ?>" target="_blank" rel="noopener"><?php echo unit_e($sharePaymentUrl); ?></a></p></section><?php endif; ?>
<section class="panel"><h2>Antrean Bukti Pembayaran (<?php echo count($pendingClaims); ?>)</h2><p class="spmb-tip">Cocokkan bukti dengan mutasi rekening sebelum menyetujui. Setelah disetujui, nominal langsung terakumulasi pada data pendaftar.</p><?php foreach($pendingClaims as $claim): ?><div class="spmb-claim"><div class="spmb-claim-head"><div><strong><?php echo unit_e($claim['student_name']); ?> · Rp <?php echo number_format((float)$claim['claimed_amount'],0,',','.'); ?></strong><br><small><?php echo unit_e($claim['registration_number']); ?> · <?php echo unit_e($claim['payment_date']); ?> · <?php echo unit_e($claim['payment_method']); ?></small></div><?php if($claim['proof_path']): ?><a href="?tab=enrollments&amp;unit=<?php echo unit_e($scope); ?>&amp;proof_spmb=<?php echo (int)$claim['id']; ?>" target="_blank" rel="noopener">Lihat Bukti</a><?php endif; ?></div><form method="post"><input type="hidden" name="csrf" value="<?php echo unit_e($csrf); ?>"><input type="hidden" name="action" value="review_spmb_payment"><input type="hidden" name="claim_id" value="<?php echo (int)$claim['id']; ?>"><label>Nominal di mutasi (Rp)<input type="number" name="confirmed_amount" min="1" step="1" value="<?php echo (int)$claim['claimed_amount']; ?>"></label><label>Referensi mutasi / transaksi<input name="bank_reference" value="<?php echo unit_e($claim['reference_number']); ?>" placeholder="Wajib untuk transfer"></label><label>Catatan<input name="review_notes" placeholder="Alasan jika ditolak"></label><div class="actions"><button name="decision" value="verified">Setujui &amp; Akumulasikan</button><button class="reject" name="decision" value="rejected">Tolak</button></div></form></div><?php endforeach; ?><?php if(!$pendingClaims): ?><p class="muted">Tidak ada bukti yang menunggu pemeriksaan.</p><?php endif; ?></section>
<?php if($verifiedClaims): ?><section class="panel"><h2>Pembayaran Terverifikasi Terbaru</h2><div class="spmb-table-wrap"><table><tr><th>Pendaftar</th><th>Nominal</th><th>Referensi</th><th>Tanggal Verifikasi</th><th>Aksi</th></tr><?php foreach($verifiedClaims as $claim): ?><tr><td><?php echo unit_e($claim['student_name']); ?><br><small><?php echo unit_e($claim['registration_number']); ?></small></td><td>Rp <?php echo number_format((float)$claim['claimed_amount'],0,',','.'); ?></td><td><?php echo unit_e($claim['verified_reference'] ?: '-'); ?></td><td><?php echo unit_e($claim['reviewed_at']); ?></td><td><form method="post"><input type="hidden" name="csrf" value="<?php echo unit_e($csrf); ?>"><input type="hidden" name="action" value="void_spmb_payment"><input type="hidden" name="claim_id" value="<?php echo (int)$claim['id']; ?>"><input name="reason" placeholder="Alasan pembatalan" required><button class="reject">Batalkan verifikasi</button></form></td></tr><?php endforeach; ?></table></div></section><?php endif; ?>
<section class="panel">
  <div class="spmb-head"><div><h2>Rekap Pendaftar SPMB <?php echo unit_e($allUnits[$scope]); ?></h2><p class="muted">Seluruh calon siswa di unit ini, dari semua kelas tujuan.</p></div><a class="spmb-export" href="?<?php echo unit_e(http_build_query(['tab'=>'enrollments','unit'=>$scope,'year'=>$filters['year'],'class'=>$filters['class'],'export_spmb'=>1])); ?>">Unduh Excel (.xlsx)</a></div>
  <form class="spmb-filter" method="get"><input type="hidden" name="tab" value="enrollments"><input type="hidden" name="unit" value="<?php echo unit_e($scope); ?>">
    <label>Tahun ajaran<select name="year"><option value="">Semua tahun</option><?php foreach($years as $year): ?><option value="<?php echo unit_e($year); ?>" <?php echo $filters['year']===$year?'selected':''; ?>><?php echo unit_e($year); ?></option><?php endforeach; ?></select></label>
    <label>Kelas tujuan<select name="class"><option value="">Semua kelas</option><?php foreach(spmb_entry_classes($scope) as $class): ?><option value="<?php echo unit_e($class); ?>" <?php echo $filters['class']===$class?'selected':''; ?>><?php echo unit_e($class); ?></option><?php endforeach; ?><option value="Belum ditentukan" <?php echo $filters['class']==='Belum ditentukan'?'selected':''; ?>>Belum ditentukan (data lama)</option></select></label>
    <button type="submit">Tampilkan</button><a href="?tab=enrollments&amp;unit=<?php echo unit_e($scope); ?>">Reset</a>
  </form>
  <div class="spmb-summary"><div><span>Total pendaftar</span><strong><?php echo count($rows); ?></strong></div><?php foreach($counts as $class=>$count): ?><div><span><?php echo unit_e($class); ?></span><strong><?php echo $count; ?></strong></div><?php endforeach; ?></div>
  <div class="spmb-table-wrap"><table class="spmb-table"><thead><tr><th>No</th><th>No. Registrasi</th><th>Calon Siswa</th><th>Kelas Tujuan</th><th>Tahun Ajaran</th><th>Orang Tua</th><th>WhatsApp</th><th>Status SPMB</th><th>Tagihan</th><th>Terverifikasi</th><th>Status Bayar</th><th>Daftar</th><th>Aksi</th></tr></thead><tbody>
  <?php foreach($rows as $index=>$row): ?><tr><td><?php echo $index+1; ?></td><td><?php echo unit_e($row['registration_number'] ?: '-'); ?></td><td><strong><?php echo unit_e($row['student_name']); ?></strong></td><td><?php echo unit_e($row['entry_class'] ?: 'Belum ditentukan'); ?></td><td><?php echo unit_e($row['academic_year']); ?><?php if($row['admission_track']==='waiting_list'): ?><br><small>Waiting List</small><?php endif; ?></td><td><?php echo unit_e($row['parent_name']); ?></td><td><a href="tel:<?php echo unit_e(preg_replace('/[^0-9+]/','',$row['whatsapp'])); ?>"><?php echo unit_e($row['whatsapp']); ?></a></td><td><?php echo unit_e($statusLabels[$row['registration_status']] ?? $row['registration_status']); ?></td><td>Rp <?php echo number_format((float)($row['total_due'] ?? 0),0,',','.'); ?></td><td><strong>Rp <?php echo number_format((float)($row['payment_amount'] ?? 0),0,',','.'); ?></strong></td><td><?php echo unit_e(ucwords(str_replace('_',' ',(string)($row['payment_status'] ?? 'belum_bayar')))); ?></td><td><?php echo unit_e(tanggal_indo($row['created_at'])); ?></td><td><?php if(!empty($row['source'])): ?><span class="muted">Data lama</span><?php else: ?><form method="post"><input type="hidden" name="csrf" value="<?php echo unit_e($csrf); ?>"><input type="hidden" name="action" value="update_spmb_status"><input type="hidden" name="id" value="<?php echo (int)$row['id']; ?>"><select name="status" aria-label="Status <?php echo unit_e($row['student_name']); ?>"><?php foreach($statusLabels as $key=>$label): ?><option value="<?php echo $key; ?>" <?php echo $row['registration_status']===$key?'selected':''; ?>><?php echo unit_e($label); ?></option><?php endforeach; ?></select><button>Simpan</button></form><a href="?tab=enrollments&amp;unit=<?php echo unit_e($scope); ?>&amp;payment_link_spmb=<?php echo (int)$row['id']; ?>">Tautan Bukti</a><?php endif; ?></td></tr><?php endforeach; ?>
  <?php if(!$rows): ?><tr><td colspan="13" class="muted">Belum ada pendaftar sesuai filter.</td></tr><?php endif; ?></tbody></table></div>
</section>
